// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint cBalBefore = address(c).balance;
        uint256 myBalBefore;
        try c.balances(address(this)) returns (uint256 __r) { myBalBefore = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint cBalAfter = address(c).balance;
        uint256 myBalAfter;
        try c.balances(address(this)) returns (uint256 __r) { myBalAfter = __r; } catch { return; }
        assertTrue(cBalAfter == cBalBefore + amount && myBalAfter == myBalBefore + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
